/**
 * Extra sample data for the podcast-block stories: artwork (inline SVG data URIs, so
 * stories stay offline), a show.fm-hosted episode, a paginated/filterable `/api/episodes`
 * handler, and a long guest list. Shapes match lib/episodes/dto.ts and lib/guests.ts.
 */
import type { EpisodeCard, EpisodeListResponse } from "@/lib/episodes/dto";
import type { AggregatedGuest, GuestsResponse } from "@/lib/guests";
import { episodes as baseEpisodes, guests as baseGuests } from "./fixtures";

/** Square abstract artwork in the site palette (graphite + apricot). */
export function artwork(seed = 0): string {
  const hue = [28, 14, 40, 200][seed % 4];
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 400"><rect width="400" height="400" fill="#2a2624"/><circle cx="${110 + (seed % 5) * 20}" cy="140" r="110" fill="hsl(${hue} 80% 62%)"/><circle cx="280" cy="${250 - (seed % 4) * 10}" r="90" fill="hsl(${hue + 30} 40% 30%)"/><rect x="40" y="320" width="320" height="14" rx="7" fill="#f2e9e1" opacity=".85"/><rect x="40" y="346" width="200" height="14" rx="7" fill="#f2e9e1" opacity=".45"/></svg>`;
  return `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`;
}

export function portrait(seed = 0): string {
  const hue = [28, 14, 40, 200, 160][seed % 5];
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200"><rect width="200" height="200" fill="hsl(${hue} 30% 24%)"/><circle cx="100" cy="82" r="38" fill="hsl(${hue} 60% 70%)"/><path d="M30 200c6-48 40-70 70-70s64 22 70 70z" fill="hsl(${hue} 60% 70%)"/></svg>`;
  return `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`;
}

