export const listOf = (...eps: EpisodeCard[]): EpisodeListResponse => ({
  episodes: eps,
  nextCursor: null,
  origin: "wordpress",
  seasons: [1, 2],
});

/** ~30 episodes across two seasons, plus a bonus and a trailer, with artwork. */
const TOPICS = [
  "Keeping an open source project alive",
  "Docs are a community, too",
  "The first contribution",
  "Burnout, and what to do instead",
  "Why office hours beat a forum",
  "Writing a code of conduct people read",
  "Maintainers on mentoring",
  "Measuring DevRel without lying",
];
const GUEST_POOL = ["Ada Moreno", "Priya Nair", "Sam Okafor", "Lena Fischer", "Wei Zhang", "Noor Haddad"];

export const manyEpisodes: EpisodeCard[] = Array.from({ length: 30 }, (_, i): EpisodeCard => {
  const n = 36 - i;
  const season = n > 24 ? 2 : 1;
  const topic = TOPICS[i % TOPICS.length];
  return {
    ...baseEpisodes[0],
    id: `wp-${2000 - i}`,
    slug: `episode-${n}`,
    title: i === 5 ? `Episode ${n}: A deliberately long episode title that should wrap onto a second and third line in the card` : `Episode ${n}: ${topic}`,
    description: `A conversation about ${topic.toLowerCase()}, with stories from people who have done it the hard way.`,
    number: n,
    season,
    type: "full",
    publishedAt: new Date(Date.UTC(2026, 9, 16) - i * 14 * 86400000).toISOString(),
    artworkUrl: i % 3 === 0 ? null : artwork(i),
    durationSeconds: 1800 + ((i * 397) % 2400),
    guests: i % 4 === 3 ? [] : [{ name: GUEST_POOL[i % GUEST_POOL.length], role: "Guest", photoUrl: null }],
    audio: null,
  };
});
manyEpisodes.splice(7, 0, { ...baseEpisodes[3], id: "wp-bonus", artworkUrl: artwork(2) });
manyEpisodes.splice(20, 0, { ...baseEpisodes[5], id: "wp-trailer" });

/**
 * `/api/episodes` stand-in: honours `limit`, `season`, `type` (comma list) and an offset
 * `cursor`, like lib/episodes/filter.ts. `seasons` only on the first page.
 */
export function episodesHandler(all: EpisodeCard[] = manyEpisodes) {
  return (url: URL) => {
    const q = url.searchParams;
    const limit = Number(q.get("limit") ?? 12);
    const season = q.get("season");
    const types = q.get("type")?.split(",").filter(Boolean);
    const offset = Number(q.get("cursor") ?? 0);
    const filtered = all.filter((e) => (!season || e.season === Number(season)) && (!types?.length || types.includes(e.type)));
    const page = filtered.slice(offset, offset + limit);
    const next = offset + limit < filtered.length ? String(offset + limit) : null;
    const body: EpisodeListResponse = { episodes: page, nextCursor: next, origin: "wordpress", ...(offset === 0 ? { seasons: [1, 2] } : {}) };
    return { body, delayMs: offset ? 400 : 0 };
  };
}

